<?php
declare(strict_types=1);
function stage57Document(string $language,array $citations,array $references):array {
 $labels=$language==='en'?['Introduction','Methods','Results and Discussion','Conclusions','References']:['Introducción','Métodos','Resultados y Discusión','Conclusiones','Referencias'];
 return countDocument(array_merge([$labels[0]],$citations,array_slice($labels,1),$references));
}
function stage57Analysis(string $language,array $citations,array $references):array {return apaResults(stage57Document($language,$citations,$references),$language);}
foreach(['en','es']as$lang){
 $word=$lang==='en'?'and':'y';
 $single='Silva, A. (2020). Synthetic work. Example Publisher.';
 $two='Silva, A., & Costa, B. (2020). Synthetic work. Example Publisher.';
 $three='Silva, A., Costa, B., & Lima, C. (2020). Synthetic work. Example Publisher.';
 foreach(['(Silva, 2020).','Silva (2020).','According to Silva (2020).','Según Silva (2020).',"Silva $word Costa (2020).",'(Silva & Costa, 2020).','Silva et al. (2020).','(Silva et al., 2020).']as$text){
  test('citação multilíngue segura liga autoria e ano '.$lang.md5($text),function()use($lang,$text,$single,$two,$three){$ref=strpos($text,'et al.')!==false?$three:(strpos($text,'Costa')!==false?$two:$single);$r=stage57Analysis($lang,[$text],[$ref]);$a=$r['references.apa7']['evidence']['analysis'];same(true,$a['segmentation_complete']);same(true,$a['closed_subset']);same(1,$a['matched_citations']);same('conforme',$r['references.citation_matching']['status']);same('conforme',$r['references.apa7.citation_format']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);same($lang,$a['language']);});
 }
 foreach([['(Silva '.$word.' Costa, 2020).',$two,'parenthetical_authors_require_ampersand'],['Silva & Costa (2020).',$two,'narrative_authors_require_conjunction'],['(Silva, Costa, & Lima, 2020).',$three,'three_or_more_authors_require_et_al'],['(Silva et al, 2020).',$three,'et_al_period'],['(Silva,2020).',$single,'citation_spacing'],['(Silva, 2020, pp. 3).',$single,'citation_page_marker'],['(Silva, 2020, pp. 12–3).',$single,'citation_page_range_order']]as$case){test('erro comprovado de citação bloqueia '.$lang.$case[2],function()use($lang,$case){$r=stage57Analysis($lang,[$case[0]],[$case[1]]);same('não conforme',$r['references.apa7.citation_format']['status']);same('not_accepted',$r['references.apa7']['evidence']['admission_policy']['decision']);same(true,in_array($case[2],$r['references.apa7']['evidence']['analysis']['citation_style_samples'][0]['issues'],true));});}
 test('ausência literal só no subconjunto fechado '.$lang,function()use($lang,$single){$r=stage57Analysis($lang,['(Absent, 2018).'],[$single]);same('não conforme',$r['references.citation_matching']['status']);same('not_accepted',$r['references.apa7']['evidence']['admission_policy']['decision']);});
 foreach(['duplicate','unparsed','bibliography','missing_core','mixed_labels','foreign_heading','quoted','numeric','compound','language_conjunction','generic_word','date_special']as$case){test('contexto ambíguo não prova ausência ou conformidade APA '.$lang.$case,function()use($lang,$single,$two,$case){
  $texts=['(Absent, 2018).'];$refs=[$single];
  if($case==='duplicate'){$texts=['(Silva, 2020).'];$refs=[$single,$single];}elseif($case==='unparsed'){$refs[]='Unrecognized bibliographic data';}elseif($case==='quoted'){$texts=['“(Absent, 2018)”'];}elseif($case==='numeric'){$texts=['[1]'];}elseif($case==='compound'){$texts=['(Cruz, 2020).'];$refs=['García de la Cruz, A. (2020). Synthetic work. Publisher.'];}elseif($case==='language_conjunction'){$texts=[$lang==='en'?'Silva y Costa (2020).':'Silva and Costa (2020).'];$refs=[$two];}elseif($case==='generic_word'){$texts=[$lang==='en'?'Figure (2020).':'Tabla (2020).'];}elseif($case==='date_special'){$texts=['(Silva, s.f.).'];$refs=['Silva, A. (s.f.). Synthetic work. Publisher.'];}
  $d=stage57Document($lang,$texts,$refs);
  if($case==='bibliography'){$d['paragraphs'][count($d['paragraphs'])-count($refs)-1]['text']=$lang==='en'?'Bibliography':'Bibliografía';}elseif($case==='missing_core'){$d['paragraphs'][2]['text']='Unsupported title';}elseif($case==='mixed_labels'){$d['paragraphs'][0]['text']='Introdução';}elseif($case==='foreign_heading'){$d['paragraphs'][1]['outline']=['known'=>true,'level'=>1];}
  $r=apaResults($d,$lang);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);same('indeterminado',$r['references.apa7.citation_format']['status']);
  if($case==='language_conjunction'){same('conforme',$r['references.citation_matching']['status']);same(true,in_array('citation_language_conjunction_review',$r['references.apa7']['evidence']['analysis']['citation_style_samples'][0]['issues'],true));}else{same('indeterminado',$r['references.citation_matching']['status']);}
 });}
 $marker=$lang==='en'?'as cited in':'como se citó en';
 foreach([$marker,'apud']as$m){test('secundária liga só a fonte consultada '.$lang.$m,function()use($lang,$single,$m){$r=stage57Analysis($lang,['(Original, 1900, '.$m.' Silva, 2020).'],[$single]);$a=$r['references.apa7']['evidence']['analysis'];same(1,$a['matched_citations']);same(0,$a['unresolved_citations']);same(true,$a['citation_samples'][0]['secondary']);same($m==='apud'?'not_accepted':'manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);if($m==='apud'){same(true,strpos(implode(' ',$a['citation_style_samples'][0]['guidance']),$lang==='en'?'as cited in':'como se citó en')!==false);}});}
 test('data completa liga chave declarada sem certificar identidade '.$lang,function()use($lang){$r=stage57Analysis($lang,['(Silva, 2020).'],['Silva, A. (2020, May 2). Synthetic page. Site. https://synthetic.invalid/']);same('conforme',$r['references.citation_matching']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
 test('idioma declarado incompatível com títulos portugueses não é convertido '.$lang,function()use($lang){$r=apaResults(referenceDocument(),$lang);same(false,$r['references.apa7']['evidence']['analysis']['segmentation_complete']);same('indeterminado',$r['references.citation_matching']['status']);});
 test('leitura parcial mantém contexto et al incompleto '.$lang,function()use($lang,$three){$body=stage57Document($lang,['(Silva et al., 2020).'],[$three]);$d=['available'=>false,'sha256'=>$body['sha256'],'reference_body'=>$body];$r=apaResults($d,$lang);same(false,$r['references.apa7']['evidence']['analysis']['et_al_context_complete']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
}
foreach(['y','e']as$conjunction){test('conjunções espanholas y e não exigem inferência fonética '.$conjunction,function()use($conjunction){$r=stage57Analysis('es',['Silva '.$conjunction.' Iglesias (2020).'],['Silva, A., & Iglesias, B. (2020). Synthetic work. Publisher.']);same('conforme',$r['references.apa7.citation_format']['status']);});}
test('narrativa espanhola com transcrição mantém revisão privada sem texto',function(){$r=stage57Analysis('es',['Silva (2020) señala “TEXTO_PRIVADO” (p. 10).'],['Silva, A. (2020). Synthetic work. Publisher.']);$a=$r['references.apa7']['evidence']['analysis'];same(1,$a['direct_quote_counts']['candidate_count']);same('indeterminado',$r['references.apa7.citation_format']['status']);same(false,strpos(json_encode($a),'TEXTO_PRIVADO')!==false);});
foreach(['en','es']as$lang){
 test('adaptador e minuta usam idioma explícito '.$lang,function()use($lang){withDeskPanel(function($s,$r,$form,$pub,$path)use($lang){
  $d=stage57Document($lang,['Silva & Costa (2020).'],['Silva, A., & Costa, B. (2020). Synthetic work. Publisher.']);$texts=array_column($d['paragraphs'],'text');$z=new ZipArchive();$z->open($path);$z->addFromString('word/document.xml',docxParts(docxBody($texts))['word/document.xml']);$z->close();$form->submission->data['locale']=$lang==='en'?'en_US':'es_ES';
  $a=(new EstrabaoAdmissionBridge())->analyze($form);same('not_accepted',$a['decision']);same(false,$a['reviewable']);same($lang,$a['binding']['language']);same('28.0.0',$a['binding']['rule_version']);same('0.43.0',$a['binding']['engine_version']);
  $r->vars['fingerprint']=$a['fingerprint'];$draft=$s->draft($r,17);same(true,count($draft['draft']['corrections'])>0);same('0.43.0',$draft['draft']['source_engine_version']);reviewPost($s,$r);reviewRejects(function()use($s,$r){$s->save($r,17);});
 });});
 test('liberação anterior ao motor multilíngue é invalidada '.$lang,function()use($lang){withDeskPanel(function($s,$r,$form,$pub,$path,$dir)use($lang){
  $d=stage57Document($lang,['(Silva, 2020).'],['Silva, A. (2020). Synthetic work. Publisher.']);$z=new ZipArchive();$z->open($path);$z->addFromString('word/document.xml',docxParts(docxBody(array_column($d['paragraphs'],'text')))['word/document.xml']);$z->close();$form->submission->data['locale']=$lang==='en'?'en_US':'es_ES';
  $a=(new EstrabaoAdmissionBridge())->analyze($form);$old=$a['binding'];$old['engine_version']='0.41.0';$old['rule_version']='26.0.0';$fingerprint=hash('sha256',json_encode($old));
  (new EstrabaoAdmissionReviewStore())->transaction(3,17,function(&$l)use($fingerprint){$l['events'][]=['sequence'=>1,'action'=>'approve','reviewer_id'=>77,'recorded_at'=>'2026-11-19T12:00:00Z','fingerprint'=>$fingerprint];});
  same(false,$s->view($r,17)['release_active']);same(1,$s->view($r,17)['revision']);same(true,$a['reviewable']);
 });});
}
